// Package repository is the PostgreSQL adapter of the carbon domain (queries generated by sqlc).
package repository

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/quixgit/greenops-reliabilix/backend/internal/carbon/domain"
	"github.com/quixgit/greenops-reliabilix/backend/internal/carbon/repository/db"
	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/database"
)

type Postgres struct{ Pool *pgxpool.Pool }

func totals(ctx context.Context, q *db.Queries, tenantID string, project *string, from, to time.Time, version string) (domain.Totals, error) {
	row, err := q.CarbonTotals(ctx, db.CarbonTotalsParams{TenantID: tenantID, ProjectID: project, MethodologyVersion: version, FromTs: from, ToTs: to})
	if err != nil {
		return domain.Totals{}, err
	}
	t := domain.Totals{EnergyKWh: row.EnergyKwh, CO2eKg: row.CarbonKgCo2e, Rows: row.RowCount, Days: int(row.Days)}
	if t.EnergyKWh > 0 {
		t.IntensityGPerKWh = t.CO2eKg * 1000 / t.EnergyKWh
	}
	if row.SciUnits > 0 {
		sci := row.SciGrams / row.SciUnits
		t.SCI = &sci
	}
	return t, nil
}

// Summary returns the window and the preceding window of equal length.
func (r Postgres) Summary(ctx context.Context, tenantID string, project *string, from, to time.Time) (s domain.Summary, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		q := db.New(tx)
		var err error
		if s.Current, err = totals(ctx, q, tenantID, project, from, to, domain.MethodologyVersion); err != nil {
			return err
		}
		s.Previous, err = totals(ctx, q, tenantID, project, from.Add(-to.Sub(from)), from, domain.MethodologyVersion)
		return err
	})
	return
}

// VersionTotals aggregates the stored rows of one methodology version.
func (r Postgres) VersionTotals(ctx context.Context, tenantID string, project *string, from, to time.Time, version string) (t domain.Totals, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		var err error
		t, err = totals(ctx, db.New(tx), tenantID, project, from, to, version)
		return err
	})
	return
}

func (r Postgres) Trend(ctx context.Context, tenantID string, project *string, from, to time.Time) ([]domain.TrendPoint, error) {
	out := []domain.TrendPoint{}
	err := database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).CarbonTrend(ctx, db.CarbonTrendParams{TenantID: tenantID, ProjectID: project, MethodologyVersion: domain.MethodologyVersion, FromTs: from, ToTs: to})
		for _, x := range rows {
			out = append(out, domain.TrendPoint{Day: x.Day, CO2eKg: x.CarbonKgCo2e})
		}
		return err
	})
	return out, err
}

const batchSize = 500

// ReplaceCalculations makes [from, to) of the given methodology version equal to calcs, atomically:
// stale rows are deleted and the new ones upserted in one transaction, so readers never see a half-written window.
// Partitions are ensured first (see usage repository).
func (r Postgres) ReplaceCalculations(ctx context.Context, tenantID, projectID string, from, to time.Time, version string, calcs []domain.Calculation) error {
	months := map[time.Time]bool{}
	for _, c := range calcs {
		months[time.Date(c.PeriodStart.Year(), c.PeriodStart.Month(), 1, 0, 0, 0, 0, time.UTC)] = true
	}
	for m := range months {
		if _, err := r.Pool.Exec(ctx, `SELECT platform.ensure_month_partition('carbon.calculations', 'period_start', $1::date)`, m); err != nil {
			return err
		}
	}
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.DeleteCalculationsInWindow(ctx, db.DeleteCalculationsInWindowParams{
			TenantID: tenantID, ProjectID: projectID, FromTs: from, ToTs: to, MethodologyVersion: version}); err != nil {
			return err
		}
		for start := 0; start < len(calcs); start += batchSize {
			end := min(start+batchSize, len(calcs))
			params := make([]db.UpsertCalculationParams, 0, end-start)
			for _, c := range calcs[start:end] {
				params = append(params, db.UpsertCalculationParams{TenantID: tenantID, ProjectID: projectID, Provider: c.Provider, RegionID: c.RegionID,
					ServiceName: c.ServiceName, ServiceCategory: c.ServiceCategory, Method: string(c.Method), PeriodStart: c.PeriodStart, PeriodEnd: c.PeriodEnd,
					EnergyKwh: c.EnergyKWh, IntensityGPerKwh: c.IntensityGPerKWh, EmbodiedG: c.EmbodiedG, CarbonKgCo2e: c.CO2eKg,
					FunctionalUnits: c.FunctionalUnits, SciScore: c.SCIScore, MethodologyVersion: c.MethodologyVersion,
					IntensitySource: nilIfEmpty(c.IntensitySource), IntensityBasis: nilIfEmpty(c.IntensityBasis)})
			}
			br := q.UpsertCalculation(ctx, params)
			var first error
			br.Exec(func(_ int, err error) {
				if err != nil && first == nil {
					first = err
				}
			})
			if err := br.Close(); err != nil && first == nil {
				first = err
			}
			if first != nil {
				return first
			}
		}
		return nil
	})
}

// SaveGridIntensity stores a reading in the global reference table (idempotent; no tenant).
func (r Postgres) SaveGridIntensity(ctx context.Context, provider, region string, at time.Time, gPerKWh float64, forecast bool, measure, resolution string) error {
	if measure == "" {
		measure = domain.MeasureAverage
	}
	if resolution == "" {
		resolution = "hourly"
	}
	return db.New(r.Pool).SaveGridIntensity(ctx, db.SaveGridIntensityParams{Provider: provider, RegionID: region, Ts: at, GCo2ePerKwh: gPerKWh, IsForecast: forecast, Measure: measure, Resolution: resolution})
}

// Monthly implements domain.IntensityReader.
func (r Postgres) Monthly(ctx context.Context, region, provider string, day time.Time) (float64, bool, error) {
	g, err := db.New(r.Pool).IntensityMonthly(ctx, db.IntensityMonthlyParams{RegionID: region, Provider: provider, Day: day})
	if database.IsNotFound(err) {
		return 0, false, nil
	}
	return g, err == nil, err
}

// MonthlyHistory returns the published monthly figures of a region that cover [from, to).
func (r Postgres) MonthlyHistory(ctx context.Context, region string, from, to time.Time) ([]domain.MonthlyRow, error) {
	rows, err := db.New(r.Pool).IntensityMonthlyHistory(ctx, db.IntensityMonthlyHistoryParams{RegionID: region, FromTs: from, ToTs: to})
	if err != nil {
		return nil, err
	}
	out := make([]domain.MonthlyRow, 0, len(rows))
	for _, x := range rows {
		out = append(out, domain.MonthlyRow{Month: x.Month, Provider: x.Provider, G: x.G})
	}
	return out, nil
}

// DayStats implements domain.IntensityReader.
func (r Postgres) DayStats(ctx context.Context, region, provider string, from, to time.Time) (float64, int, error) {
	row, err := db.New(r.Pool).IntensityDayStats(ctx, db.IntensityDayStatsParams{RegionID: region, Provider: provider, FromTs: from, ToTs: to})
	if err != nil {
		return 0, 0, err
	}
	return row.G, int(row.N), nil
}

// Latest implements domain.IntensityReader.
func (r Postgres) Latest(ctx context.Context, region, provider string, before *time.Time) (float64, time.Time, bool, error) {
	row, err := db.New(r.Pool).IntensityLatest(ctx, db.IntensityLatestParams{RegionID: region, Provider: provider, Before: before})
	if database.IsNotFound(err) {
		return 0, time.Time{}, false, nil
	}
	if err != nil {
		return 0, time.Time{}, false, err
	}
	return row.G, row.Ts, true, nil
}

// History returns each source's daily readings of a region in [from, to).
func (r Postgres) History(ctx context.Context, region string, from, to time.Time) ([]domain.HistoryRow, error) {
	rows, err := db.New(r.Pool).IntensityHistory(ctx, db.IntensityHistoryParams{RegionID: region, FromTs: from, ToTs: to})
	if err != nil {
		return nil, err
	}
	out := make([]domain.HistoryRow, 0, len(rows))
	for _, x := range rows {
		out = append(out, domain.HistoryRow{Day: x.Day, Provider: x.Provider, Mean: x.Mean, Lo: x.Lo, Hi: x.Hi, N: int(x.N)})
	}
	return out, nil
}

// Regions lists the regions the organization has carbon in, largest first.
func (r Postgres) Regions(ctx context.Context, tenantID string, project *string, from, to time.Time, version string) (out []domain.RegionCarbon, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).TenantRegions(ctx, db.TenantRegionsParams{TenantID: tenantID, ProjectID: project, MethodologyVersion: version, FromTs: from, ToTs: to})
		for _, x := range rows {
			out = append(out, domain.RegionCarbon{Region: x.RegionID, CarbonKg: x.CarbonKgCo2e})
		}
		return err
	})
	return
}

// Origins breaks the carbon of a window down by where its intensities came from.
func (r Postgres) Origins(ctx context.Context, tenantID string, project *string, from, to time.Time, version string) (out []domain.IntensityOrigin, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).IntensityBasisBreakdown(ctx, db.IntensityBasisBreakdownParams{TenantID: tenantID, ProjectID: project, MethodologyVersion: version, FromTs: from, ToTs: to})
		for _, x := range rows {
			out = append(out, domain.IntensityOrigin{Source: x.Source, Basis: x.Basis, CarbonKg: x.CarbonKgCo2e})
		}
		return err
	})
	return
}

func nilIfEmpty(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// RegionsInUse lists the regions that have carbon calculations (region ids only; through a definer function).
func (r Postgres) RegionsInUse(ctx context.Context) ([]string, error) {
	rows, err := r.Pool.Query(ctx, `SELECT region_id FROM carbon.regions_in_use()`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, rows.Err()
}

// RegionCoverage reports, per region in use, how many of the last `days` days have grid data (monthly figures count).
func (r Postgres) RegionCoverage(ctx context.Context, days int) ([]domain.RegionCoverage, error) {
	return r.coverage(ctx, `SELECT region_id, covered_days, total_days FROM carbon.region_coverage($1)`, days)
}

// RegionHourlyCoverage is the same, counting only days with hourly readings.
func (r Postgres) RegionHourlyCoverage(ctx context.Context, days int) ([]domain.RegionCoverage, error) {
	return r.coverage(ctx, `SELECT region_id, covered_days, total_days FROM carbon.region_hourly_coverage($1)`, days)
}

func (r Postgres) coverage(ctx context.Context, query string, days int) ([]domain.RegionCoverage, error) {
	rows, err := r.Pool.Query(ctx, query, days)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []domain.RegionCoverage
	for rows.Next() {
		var c domain.RegionCoverage
		if err := rows.Scan(&c.Region, &c.Covered, &c.Total); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

// Forecast returns one source's stored forecast points of a region in [from, to).
func (r Postgres) Forecast(ctx context.Context, region, provider string, from, to time.Time) ([]domain.ForecastPoint, error) {
	rows, err := db.New(r.Pool).IntensityForecast(ctx, db.IntensityForecastParams{RegionID: region, Provider: provider, FromTs: from, ToTs: to})
	if err != nil {
		return nil, err
	}
	out := make([]domain.ForecastPoint, 0, len(rows))
	for _, x := range rows {
		out = append(out, domain.ForecastPoint{At: x.Ts, G: x.G})
	}
	return out, nil
}
